import { useCallback, useEffect, useState } from 'react'

import { Link, Outlet, useLocation } from 'react-router-dom'

import { Add as AddIcon } from '@mui/icons-material'
import { Container, Box, Button, Stack, CircularProgress, Alert, Tabs, Tab } from '@mui/material'

import { getTrainingPlans } from '@/api/trainingPlans'
import { useAuth } from '@/contexts/AuthContext'
import { routes } from '@/routes'
import type { TrainingPlan } from '@/types/database'

import PlanCard from './components/PlanCard'

export function PlansPage() {
  const location = useLocation()
  const isListView = location.pathname === '/plans' || location.pathname === '/plans/'

  return (
    <Container maxWidth="md" disableGutters>
      <Box sx={{ mt: { xs: 2, sm: 4 }, pb: 10, px: { xs: 1, sm: 2 } }}>
        {isListView && (
          <Box sx={{ display: 'flex', justifyContent: 'flex-end', mb: 2 }}>
            <Button
              component={Link}
              to={routes.plans.new.$()}
              variant="contained"
              startIcon={<AddIcon />}
            >
              새 계획
            </Button>
          </Box>
        )}
        {isListView ? <PlansList /> : <Outlet />}
      </Box>
    </Container>
  )
}

type PlanStatusTab = 'active' | 'paused' | 'completed'

const TAB_EMPTY_MESSAGES: Record<PlanStatusTab, string> = {
  active: '진행중인 계획이 없습니다.',
  paused: '중단된 계획이 없습니다.',
  completed: '완료된 계획이 없습니다.',
}

function PlansList() {
  const { user } = useAuth()
  const [plans, setPlans] = useState<TrainingPlan[]>([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)
  const [tab, setTab] = useState<PlanStatusTab>('active')

  const loadPlans = useCallback(async () => {
    try {
      setLoading(true)
      const data = await getTrainingPlans(user?.id)
      setPlans(data)
    } catch (err) {
      setError('훈련 계획을 불러오는데 실패했습니다.')
      // eslint-disable-next-line no-console
      console.error(err)
    } finally {
      setLoading(false)
    }
  }, [user?.id])

  useEffect(() => {
    if (user) {
      loadPlans()
    }
  }, [user, loadPlans])

  if (loading) {
    return (
      <Box sx={{ display: 'flex', justifyContent: 'center', py: 4 }}>
        <CircularProgress />
      </Box>
    )
  }

  if (error) {
    return <Alert severity="error">{error}</Alert>
  }

  if (plans.length === 0) {
    return <Alert severity="info">아직 훈련 계획이 없습니다. 새 계획을 만들어보세요!</Alert>
  }

  const plansByTab: Record<PlanStatusTab, TrainingPlan[]> = {
    active: plans.filter((p) => !p.completed_at && !p.paused_at),
    paused: plans.filter((p) => !p.completed_at && p.paused_at),
    completed: plans.filter((p) => p.completed_at),
  }
  const visiblePlans = plansByTab[tab]

  return (
    <Stack spacing={2}>
      <Tabs value={tab} onChange={(_, value: PlanStatusTab) => setTab(value)}>
        <Tab value="active" label={`진행중 (${plansByTab.active.length})`} />
        <Tab value="paused" label={`중단 (${plansByTab.paused.length})`} />
        <Tab value="completed" label={`완료 (${plansByTab.completed.length})`} />
      </Tabs>
      {visiblePlans.length === 0 ? (
        <Alert severity="info">{TAB_EMPTY_MESSAGES[tab]}</Alert>
      ) : (
        visiblePlans.map((plan) => (
          <PlanCard key={plan.id} plan={plan} variant="list" onUpdate={loadPlans} />
        ))
      )}
    </Stack>
  )
}
